const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const reservoir = ee.Geometry.Polygon([[
    [-101.25, 29.65],
    [-100.75, 29.65],
    [-100.75, 29.25],
    [-101.25, 29.25],
    [-101.25, 29.65]
  ]]); // Bounding box around Amistad Reservoir

  const aug2016 = ee.DateRange('2016-08-01', '2016-08-31');
  const aug2024 = ee.DateRange('2024-08-01', '2024-08-31');

  // 2. Data Acquisition - Use JRC Global Surface Water (monthly water occurrence)
  // Band 'water_occurrence' shows frequency of water presence (0-100%) across all years
  // For specific months, we need to use the monthly dataset
  const getWaterCollection = function(dateRange) {
    return ee.ImageCollection('JRC/GSW1_4/MonthlyHistory')
      .filterBounds(reservoir)
      .filterDate(dateRange.start(), dateRange.end())
      .select('water');
  };

  const col2016 = getWaterCollection(aug2016);
  const col2024 = getWaterCollection(aug2024);

  // Check collection sizes
  const size2016 = col2016.size().getInfo();
  const size2024 = col2024.size().getInfo();

  console.log(`2016 Images: ${size2016}, 2024 Images: ${size2024}`);

  if (size2016 === 0 || size2024 === 0) {
    // Try alternative: Yearly water classification dataset
    const altCol2016 = ee.ImageCollection('JRC/GSW1_4/YearlyHistory')
      .filterBounds(reservoir)
      .filterDate('2016-01-01', '2016-12-31');
    const altCol2024 = ee.ImageCollection('JRC/GSW1_4/YearlyHistory')
      .filterBounds(reservoir)
      .filterDate('2024-01-01', '2024-12-31');

    const altSize2016 = altCol2016.size().getInfo();
    const altSize2024 = altCol2024.size().getInfo();

    console.log(`Alternative 2016: ${altSize2016}, 2024: ${altSize2024}`);

    if (altSize2016 === 0 || altSize2024 === 0) {
      console.log("<answer>C1</answer>");
      return;
    }

    // Use yearly classification (band 'waterClass' where water=2)
    const water2016 = altCol2016.first().eq(2); // Water class = 2
    const water2024 = altCol2024.first().eq(2);

    // Count water pixels
    const count2016 = water2016.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: reservoir,
      scale: 1000,
      maxPixels: 1e9
    }).get('water').getInfo();

    const count2024 = water2024.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: reservoir,
      scale: 1000,
      maxPixels: 1e9
    }).get('water').getInfo();

    console.log(`Water pixels 2016: ${count2016}, 2024: ${count2024}`);

    if (count2016 === 0 && count2024 === 0) {
      console.log("<answer>C2</answer>");
      return;
    }

    if (count2016 === null || count2024 === null || 
        count2016 === undefined || count2024 === undefined) {
      console.log("<answer>C3</answer>");
      return;
    }

    const decrease = count2024 < count2016;
    console.log(`Decrease: ${decrease}`);
    console.log(decrease ? "<answer>A</answer>" : "<answer>B</answer>");
    return;
  }

  // 3. Processing - Use monthly data
  // Monthly water classification: 0=no data, 1=not water, 2=water
  const water2016 = col2016.map(img => img.eq(2)).sum(); // Sum of water months
  const water2024 = col2024.map(img => img.eq(2)).sum();

  // Count water pixels (pixels that were water in any image of the month)
  const count2016 = water2016.gt(0).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: reservoir,
    scale: 1000,
    maxPixels: 1e9
  }).get('water').getInfo();

  const count2024 = water2024.gt(0).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: reservoir,
    scale: 1000,
    maxPixels: 1e9
  }).get('water').getInfo();

  console.log(`Water pixels 2016: ${count2016}, 2024: ${count2024}`);

  // 4. Validation & Final Answer
  if (count2016 === 0 && count2024 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (count2016 === null || count2024 === null || 
      count2016 === undefined || count2024 === undefined ||
      isNaN(count2016) || isNaN(count2024)) {
    console.log("<answer>C3</answer>");
    return;
  }

  const decrease = count2024 < count2016;
  console.log(`Decrease: ${decrease}`);
  console.log(decrease ? "<answer>A</answer>" : "<answer>B</answer>");
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
